function freshDate(daysAgo: number) {
  const date = new Date()
  date.setDate(date.getDate() - daysAgo)
  return new Intl.DateTimeFormat('es-NI', { day: '2-digit', month: 'short' }).format(date)
}

const ES_MONTHS: Record<string, string> = {
  ene: '01', feb: '02', mar: '03', abr: '04', may: '05', jun: '06',
  jul: '07', ago: '08', sep: '09', sept: '09', oct: '10', nov: '11', dic: '12',
  enero: '01', febrero: '02', marzo: '03', abril: '04', mayo: '05', junio: '06',
  julio: '07', agosto: '08', septiembre: '09', octubre: '10', noviembre: '11', diciembre: '12',
}

const LOGISTICS_SERVICE_FEE_CS = 15

export function profileCanPayInvoices(role: string | undefined, canPayInvoices: boolean | number | undefined) {
  return role === 'supervisor' || canPayInvoices === true || canPayInvoices === 1
}

function parseManaguaSchedule(dateText: string | undefined, timeText: string | undefined): Date | null {
  const dateMatch = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(dateText ?? '').trim())
  const timeMatch = /^(\d{2}):(\d{2})$/.exec(String(timeText ?? '00:00').trim())
  if (!dateMatch || !timeMatch) return null
  const year = Number(dateMatch[1])
  const month = Number(dateMatch[2])
  const day = Number(dateMatch[3])
  const hour = Number(timeMatch[1])
  const minute = Number(timeMatch[2])
  if (month < 1 || month > 12 || day < 1 || day > 31 || hour > 23 || minute > 59) return null
  const calendarDate = new Date(Date.UTC(year, month - 1, day))
  if (calendarDate.getUTCFullYear() !== year || calendarDate.getUTCMonth() !== month - 1 || calendarDate.getUTCDate() !== day) return null
  // Nicaragua uses UTC-06:00 without seasonal clock changes.
  return new Date(Date.UTC(year, month - 1, day, hour + 6, minute))
}

function monthKeyOf(dateText: string | undefined): string {
  if (!dateText) return ''
  const match = /(\d{1,2})[ /.-]+([a-zA-Záéíóúñ]+)(?:[ /.-]+(\d{4}))?/.exec(dateText.trim())
  if (!match) return ''
  const month = ES_MONTHS[match[2].toLowerCase()]
  if (!month) return ''
  const year = match[3] ?? String(new Date().getFullYear())
  return `${year}-${month}`
}

function currentMonthKey(): string {
  const now = new Date()
  return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`
}

function formatDateOffset(daysAhead: number) {
  const date = new Date()
  date.setDate(date.getDate() + daysAhead)
  return new Intl.DateTimeFormat('es-NI', { day: '2-digit', month: 'short' }).format(date)
}

function collectOnDay(day: number) {
  const clamped = Math.max(1, Math.min(28, day))
  const now = new Date()
  if (now.getDate() <= clamped) {
    const target = new Date(now.getFullYear(), now.getMonth(), clamped)
    return new Intl.DateTimeFormat('es-NI', { day: '2-digit', month: 'short' }).format(target)
  }
  const target = new Date(now.getFullYear(), now.getMonth() + 1, clamped)
  return new Intl.DateTimeFormat('es-NI', { day: '2-digit', month: 'short' }).format(target)
}

