  private parseTripJson<T>(value: unknown, fallback: T): T {
    if (typeof value !== 'string' || !value.trim()) return fallback
    try {
      const parsed = JSON.parse(value) as T
      return parsed ?? fallback
    } catch {
      return fallback
    }
  }

